const AGENDA_ACCEPTANCE_SUCCESS_FEEDBACK_MS = 520;
const WEEK_CLEARED_SLOT_SETTLE_MS = 260;
const WEEK_MOVED_SLOT_SUPPRESSION_MS = 2 * 60 * 1000;
const WEEK_LOCALLY_DELETED_APPOINTMENT_SUPPRESSION_MS = 2 * 60 * 1000;
const WEEK_LOCALLY_DELETED_REQUEST_SUPPRESSION_MS = 2 * 60 * 1000;
type WeekPlannerSlotTouchableProps = React.ComponentProps<
  typeof HapticTouchable
> & {
  shouldBlockPress?: (touchStartedAt?: number) => boolean;
  androidPassive?: boolean;
  labelled?: boolean;
};

const WEEK_SLOT_PRESS_MOVE_CANCEL_PX = 8;
const AGENDA_SLOT_PRESS_RELEASE_GUARD_MS = 160;
const WEEK_SLOT_PRESS_FEEDBACK_STYLE = StyleSheet.create({
  active: {
    transform: [{ scale: 0.94 }, { translateY: 1 }],
    shadowOpacity: 0,
    elevation: 0,
  },
}).active;

const readWeekSlotTouchPoint = (event: unknown) => {
  const nativeEvent = (
    event as {
      nativeEvent?: { pageX?: number; pageY?: number };
    }
  )?.nativeEvent;
  const pageX = Number(nativeEvent?.pageX);
  const pageY = Number(nativeEvent?.pageY);
  return Number.isFinite(pageX) && Number.isFinite(pageY)
    ? { pageX, pageY }
    : null;
};

function NativeWeekSlotPressHint({visible,labelled=false}:{visible:boolean;labelled?:boolean}) {
  const {palette:p}=useAccessAppearance();
  return <View pointerEvents="none" style={[StyleSheet.absoluteFill,{alignItems:'center',justifyContent:'center',opacity:visible?1:0,backgroundColor:p.night?'rgba(216,194,155,.14)':'rgba(104,128,108,.13)'}]}>
    {!labelled?<Text style={{fontSize:22,lineHeight:26,fontWeight:'400',color:p.ink}}>+</Text>:null}
  </View>;
}

function AndroidWeekPlannerSlotTouchable({
  style,
  disabled,
  activeOpacity = 0.9,
  children,
  shouldBlockPress,
  androidPassive: _androidPassive,
  labelled,
  ...props
}: WeekPlannerSlotTouchableProps) {
  const touchStartedAtRef = React.useRef(0);
  const touchIsDownRef = React.useRef(false);
  const movedDuringTouchRef = React.useRef(false);
  const touchStartRef = React.useRef<{ pageX: number; pageY: number } | null>(
    null,
  );
  const { onPress, onLongPress, onPressIn, onPressOut } = props;
  const didTouchMove = (event: unknown) => {
    const start = touchStartRef.current;
    const current = readWeekSlotTouchPoint(event);
    return !!(
      start &&
      current &&
      Math.hypot(current.pageX - start.pageX, current.pageY - start.pageY) >=
        WEEK_SLOT_PRESS_MOVE_CANCEL_PX
    );
  };
  const { delayLongPress, hitSlop, pressRetentionOffset, ...pressableProps } =
    props;

  return (
    <Pressable
      {...pressableProps}
      onTouchStart={(event) => {
        touchIsDownRef.current = true;
        touchStartedAtRef.current = Date.now();
        movedDuringTouchRef.current = false;
        touchStartRef.current = readWeekSlotTouchPoint(event);
        props.onTouchStart?.(event);
      }}
      onTouchMove={(event) => {
        if (didTouchMove(event)) movedDuringTouchRef.current = true;
        props.onTouchMove?.(event);
      }}
      onTouchCancel={event=>{touchIsDownRef.current=false;movedDuringTouchRef.current=true;props.onTouchCancel?.(event);}}
      onTouchEnd={event=>{touchIsDownRef.current=false;props.onTouchEnd?.(event);}}
      disabled={disabled}
      onPress={(event) => {
        if (movedDuringTouchRef.current || didTouchMove(event) || shouldBlockPress?.(touchStartedAtRef.current)) return;
        onPress?.(event);
      }}
      onLongPress={(event) => {
        if (movedDuringTouchRef.current || didTouchMove(event) || shouldBlockPress?.(touchStartedAtRef.current)) return;
        onLongPress?.(event);
      }}
      onPressIn={(event) => {
        if (!touchIsDownRef.current) {touchStartRef.current = readWeekSlotTouchPoint(event);movedDuringTouchRef.current=false;touchStartedAtRef.current=Date.now();}
        onPressIn?.(event);
      }}
      onPressOut={(event) => onPressOut?.(event)}
      delayLongPress={typeof delayLongPress === 'number' ? delayLongPress : 420}
      hitSlop={hitSlop ?? { top: 6, left: 6, right: 6, bottom: 6 }}
      pressRetentionOffset={
        pressRetentionOffset ?? { top: 10, left: 10, right: 10, bottom: 10 }
      }
      unstable_pressDelay={0}
      android_disableSound={false}
      style={({ pressed }) => [
        style,
        pressed && !disabled && WEEK_SLOT_PRESS_FEEDBACK_STYLE,
        pressed && !disabled ? { opacity: activeOpacity } : null,
      ]}
    >
      {({pressed})=><AgendaSlotFeedbackContext.Provider value={pressed&&!disabled}>{children}<NativeWeekSlotPressHint visible={pressed&&!disabled} labelled={labelled}/></AgendaSlotFeedbackContext.Provider>}
    </Pressable>
  );
}

function WeekPlannerSlotTouchable(
  props: WeekPlannerSlotTouchableProps,
) {
  if (IS_ANDROID) {
    if (props.androidPassive) {
      return <PassiveWeekPlannerSlotFeedback {...props} />;
    }
    return <AndroidWeekPlannerSlotTouchable {...props} />;
  }

  return <NonAndroidWeekPlannerSlotTouchable {...props} />;
}

// Observe touches without claiming the responder: Android's grid still owns
// hit testing and scroll/tap arbitration for passive cells.
function PassiveWeekPlannerSlotFeedback({ style, children, disabled }: WeekPlannerSlotTouchableProps) {
  const [pressed, setPressed] = React.useState(false);
  const start = React.useRef<{ pageX: number; pageY: number } | null>(null);
  return <View
    style={[style, pressed && !disabled && WEEK_SLOT_PRESS_FEEDBACK_STYLE]}
    onTouchStart={event => { start.current = readWeekSlotTouchPoint(event); if (!disabled) setPressed(true); }}
    onTouchMove={event => {
      const point = readWeekSlotTouchPoint(event);
      if (point && start.current && Math.hypot(point.pageX - start.current.pageX, point.pageY - start.current.pageY) >= WEEK_SLOT_PRESS_MOVE_CANCEL_PX) setPressed(false);
    }}
    onTouchEnd={() => setPressed(false)}
    onTouchCancel={() => setPressed(false)}
  ><AgendaSlotFeedbackContext.Provider value={pressed&&!disabled}>{children}</AgendaSlotFeedbackContext.Provider></View>;
}

function NonAndroidWeekPlannerSlotTouchable({
  style,
  disabled,
  activeOpacity = 0.9,
  children,
  shouldBlockPress,
  androidPassive: _androidPassive,
  labelled,
  ...props
}: WeekPlannerSlotTouchableProps) {
  const [pressed, setPressed] = React.useState(false);
  const touchStartedAtRef = React.useRef(0);
  const touchIsDownRef = React.useRef(false);
  const movedDuringTouchRef = React.useRef(false);
  const touchStartRef = React.useRef<{ pageX: number; pageY: number } | null>(
    null,
  );
  const { onPress, onLongPress, onPressIn, onPressOut } = props;
  const didTouchMove = React.useCallback((event: unknown) => {
    const start = touchStartRef.current;
    const current = readWeekSlotTouchPoint(event);
    return !!(
      start &&
      current &&
      Math.hypot(current.pageX - start.pageX, current.pageY - start.pageY) >=
        WEEK_SLOT_PRESS_MOVE_CANCEL_PX
    );
  }, []);
  const handlePressIn = React.useCallback(
    (event: Parameters<NonNullable<typeof onPressIn>>[0]) => {
      if (!touchIsDownRef.current) {touchStartRef.current = readWeekSlotTouchPoint(event);movedDuringTouchRef.current=false;touchStartedAtRef.current=Date.now();}
      if (!IS_WEB && !disabled) setPressed(true);
      onPressIn?.(event);
    },
    [disabled, onPressIn],
  );
  const handlePressOut = React.useCallback(
    (event: Parameters<NonNullable<typeof onPressOut>>[0]) => {
      if (!IS_WEB) setPressed(false);
      onPressOut?.(event);
    },
    [onPressOut],
  );
  const handlePress = React.useCallback(
    (event: Parameters<NonNullable<typeof onPress>>[0]) => {
      if (movedDuringTouchRef.current || didTouchMove(event) || shouldBlockPress?.(IS_WEB ? undefined : touchStartedAtRef.current)) return;
      onPress?.(event);
    },
    [didTouchMove, onPress, shouldBlockPress],
  );
  const handleLongPress = React.useCallback(
    (event: Parameters<NonNullable<typeof onLongPress>>[0]) => {
      if (movedDuringTouchRef.current || didTouchMove(event) || shouldBlockPress?.(touchStartedAtRef.current)) return;
      onLongPress?.(event);
    },
    [didTouchMove, onLongPress, shouldBlockPress],
  );

  if (Platform.OS === 'web') {
    return (
      <HapticTouchable
        {...props}
        hapticType="none"
        pressInHapticType="none"
        onTouchStart={event => { touchIsDownRef.current = true;
        touchStartedAtRef.current = Date.now(); movedDuringTouchRef.current = false; touchStartRef.current = readWeekSlotTouchPoint(event); props.onTouchStart?.(event); }}
        onTouchMove={event => { if (didTouchMove(event)) movedDuringTouchRef.current = true; props.onTouchMove?.(event); }}
        onTouchCancel={event => { touchIsDownRef.current=false;movedDuringTouchRef.current = true; props.onTouchCancel?.(event); }}
        onTouchEnd={event=>{touchIsDownRef.current=false;props.onTouchEnd?.(event);}}
        onPress={handlePress}
        onLongPress={handleLongPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        disabled={disabled}
        activeOpacity={activeOpacity}
        style={[
          style,
          {
            cursor: disabled ? 'default' : 'pointer',
            touchAction: 'pan-y',
            userSelect: 'none',
            WebkitUserSelect: 'none',
            WebkitTapHighlightColor: 'transparent',
          } as unknown as object,
        ]}
      >
        {children}
      </HapticTouchable>
    );
  }

  return (
    <HapticTouchable
      {...props}
      onTouchStart={(event) => {
        if (!disabled) setPressed(true);
        touchIsDownRef.current = true;
        touchStartedAtRef.current = Date.now();
        movedDuringTouchRef.current = false;
        touchStartRef.current = readWeekSlotTouchPoint(event);
        props.onTouchStart?.(event);
      }}
      onTouchMove={(event) => {
        if (didTouchMove(event)) { movedDuringTouchRef.current = true; setPressed(false); }
        props.onTouchMove?.(event);
      }}
      onTouchCancel={(event) => { touchIsDownRef.current=false;movedDuringTouchRef.current = true; setPressed(false); props.onTouchCancel?.(event); }}
      onTouchEnd={(event) => { touchIsDownRef.current=false;setPressed(false); props.onTouchEnd?.(event); }}
      onPress={handlePress}
      onLongPress={handleLongPress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      // Il feedback del `+` appartiene a openQuickSlotModal, dopo che movimento
      // e scroll sono stati esclusi. Il default di HapticTouchable produrrebbe
      // su iOS un primo feedback anche per un press poi scartato e un secondo
      // feedback all'apertura effettiva.
      hapticType="none"
      pressInHapticType="none"
      pressRetentionOffset={
        props.pressRetentionOffset ?? {
          top: 10,
          left: 10,
          right: 10,
          bottom: 10,
        }
      }
      disabled={disabled}
      activeOpacity={activeOpacity}
      delayPressIn={0}
      pressScale={0.94}
      pressOpacity={1}
      style={[style, pressed && !disabled && WEEK_SLOT_PRESS_FEEDBACK_STYLE]}
    >
      <AgendaSlotFeedbackContext.Provider value={pressed&&!disabled}>{children}</AgendaSlotFeedbackContext.Provider>
      {pressed&&!disabled?<NativeWeekSlotPressHint visible labelled={labelled}/>:null}
    </HapticTouchable>
  );
}

function WeekDragTargetHighlight({
  tone = 'available',
}: {
  tone?: 'available' | 'warning' | 'overlap' | 'invalid';
}) {
  const styles=React.useContext(AgendaPremiumStyleContext)??baseAgendaStyles;

  return (
    <Reanimated.View
      pointerEvents="none"
      entering={FadeIn.duration(65).easing(Easing.out(Easing.quad))}
      exiting={FadeOut.duration(45).easing(Easing.in(Easing.quad))}
      style={[
        styles.weekDragTargetHighlight,
        tone === 'warning' && styles.weekDragTargetHighlightWarning,
        tone === 'overlap' && styles.weekDragTargetHighlightOverlap,
        tone === 'invalid' && styles.weekDragTargetHighlightInvalid,
      ]}
    >
      <View pointerEvents="none" style={styles.weekDragTargetHighlightSheen} />
      <View
        pointerEvents="none"
        style={styles.weekDragTargetHighlightInnerGlow}
      />
    </Reanimated.View>
  );
}

const buildUniqueEntityId = (prefix: string) =>
  `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
const normalizeBirthdayValue = (value?: string | null) => {
  const raw = (value ?? '').trim();
  if (!raw) return '';
  const normalized = raw.replace(/\//g, '-');
  if (/^\d{4}-\d{2}-\d{2}$/.test(normalized)) return normalized;
  return '';
};
const formatBirthdayLabel = (value?: string | null) => {
  const normalizedValue = normalizeBirthdayValue(value);
  if (!normalizedValue) return '';
  const [year, month, day] = normalizedValue.split('-');
  return `${day}/${month}/${year}`;
};
const formatNumericFieldLabel = (label: string, value: string, suffix = '') =>
  value ? `${label}: ${value}${suffix}` : label;
const normalizeAgendaCustomerIdentityText = (value?: string | null) =>
  (value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
const normalizeAgendaCustomerPhoneIdentity = (value?: string | null) =>
  limitPhoneToTenDigits(value ?? '');
type AgendaFrontendIdentityCustomer = {
  telefono?: string | null;
  email?: string | null;
  fonte?: string | null;
};
type AgendaFrontendIdentityRequest = {
  telefono?: string | null;
  email?: string | null;
  origine?: string | null;
};
const hasAgendaFrontendCustomerIdentity = ({
  selectedCustomer,
  customers,
  requests,
}: {
  selectedCustomer: AgendaFrontendIdentityCustomer;
  customers: AgendaFrontendIdentityCustomer[];
  requests: AgendaFrontendIdentityRequest[];
}) => {
  const selectedEmail = normalizeAgendaCustomerIdentityText(
    selectedCustomer.email,
  );
  const selectedPhone = normalizeAgendaCustomerPhoneIdentity(
    selectedCustomer.telefono,
  );
  const hasMatchingContact = (candidate: AgendaFrontendIdentityCustomer) => {
    const candidateEmail = normalizeAgendaCustomerIdentityText(candidate.email);
    const candidatePhone = normalizeAgendaCustomerPhoneIdentity(
      candidate.telefono,
    );

    return (
      (!!selectedEmail && candidateEmail === selectedEmail) ||
      (!!selectedPhone && candidatePhone === selectedPhone)
    );
  };

  return (
    selectedCustomer.fonte === 'frontend' ||
    customers.some(
      (customer) =>
        customer.fonte === 'frontend' && hasMatchingContact(customer),
    ) ||
    requests.some(
      (request) =>
        request.origine === 'frontend' && hasMatchingContact(request),
    )
  );
};
const matchesAgendaCustomerDisplayName = (
  firstValue?: string | null,
  secondValue?: string | null,
) => {
  const normalizedFirst = normalizeAgendaCustomerIdentityText(firstValue);
  const normalizedSecond = normalizeAgendaCustomerIdentityText(secondValue);

  if (!normalizedFirst || !normalizedSecond) {
    return false;
  }

  if (normalizedFirst === normalizedSecond) {
    return true;
  }

  const firstTokens = normalizedFirst.split(' ').filter(Boolean);
  const secondTokens = normalizedSecond.split(' ').filter(Boolean);

  if (
    firstTokens.length > 1 &&
    secondTokens.length > 1 &&
    firstTokens.every((token) => secondTokens.includes(token))
  ) {
    return true;
  }

  if (
    firstTokens.length > 1 &&
    secondTokens.length > 1 &&
    secondTokens.every((token) => firstTokens.includes(token))
  ) {
    return true;
  }

  return (
    normalizedFirst.includes(normalizedSecond) ||
    normalizedSecond.includes(normalizedFirst)
  );
};
const matchesAgendaCustomerLinkName = (
  firstValue?: string | null,
  secondValue?: string | null,
) => {
  const normalizedFirst = normalizeAgendaCustomerIdentityText(firstValue);
  const normalizedSecond = normalizeAgendaCustomerIdentityText(secondValue);

  if (!normalizedFirst || !normalizedSecond) {
    return false;
  }

  if (normalizedFirst === normalizedSecond) {
    return true;
  }

  const firstTokens = normalizedFirst.split(' ').filter(Boolean);
  const secondTokens = normalizedSecond.split(' ').filter(Boolean);

  return (
    firstTokens.length > 1 &&
    secondTokens.length > 1 &&
    firstTokens.length === secondTokens.length &&
    firstTokens.every((token) => secondTokens.includes(token))
  );
};
