const getAgendaRequestStatusRank = (item: {
  stato: 'In attesa' | 'Accettata' | 'Rifiutata' | 'Annullata';
  cancellationSource?: 'cliente' | 'salone';
}) => {
  switch (item.stato) {
    case 'Annullata':
      return item.cancellationSource === 'cliente' ? 44 : 42;
    case 'Rifiutata':
      return 40;
    case 'Accettata':
      return 30;
    case 'In attesa':
    default:
      return 10;
  }
};
const getAgendaRequestCompletenessRank = (item: {
  appointmentGroupId?: string | null;
  appointmentGroupOrder?: number | null;
  appointmentGroupSize?: number | null;
  compositionId?: string | null;
  dependencyServiceId?: string | null;
  phaseConfig?: ServicePhaseConfig | null;
  phaseOperatorAssignments?: ServicePhaseOperatorAssignments | null;
  phaseOverlapOverrides?: ServicePhaseOverlapOverrides | null;
  operatoreId?: string | null;
  operatoreNome?: string | null;
  note?: string | null;
  telefono?: string | null;
  email?: string | null;
  instagram?: string | null;
  mestiereRichiesto?: string | null;
  operatorChangeStatus?: 'pending' | 'accepted' | 'rejected' | 'expired' | null;
}) => {
  let score = 0;
  if (item.appointmentGroupId?.trim()) score += 20;
  if (typeof item.appointmentGroupOrder === 'number') score += 2;
  if (typeof item.appointmentGroupSize === 'number') score += 2;
  if (item.compositionId?.trim()) score += 4;
  if (item.dependencyServiceId?.trim()) score += 4;
  if (item.phaseConfig) score += 20;
  if (item.phaseOperatorAssignments) score += 5;
  if (item.phaseOverlapOverrides) score += 5;
  if (item.operatorChangeStatus === 'pending') score += 100;
  if (item.operatoreId?.trim()) score += 5;
  if (item.operatoreNome?.trim()) score += 4;
  if (item.note?.trim()) score += 2;
  if (item.telefono?.trim()) score += 1;
  if (item.email?.trim()) score += 1;
  if (item.instagram?.trim()) score += 1;
  if (item.mestiereRichiesto?.trim()) score += 1;
  return score;
};
const compareAgendaRequestAuthority = <
  T extends {
    id: string;
    stato: 'In attesa' | 'Accettata' | 'Rifiutata' | 'Annullata';
    createdAt?: string | null;
    cancellationSource?: 'cliente' | 'salone';
    operatoreId?: string | null;
    operatoreNome?: string | null;
    note?: string | null;
    telefono?: string | null;
    email?: string | null;
    instagram?: string | null;
    mestiereRichiesto?: string | null;
    operatorChangeStatus?:
      'pending' | 'accepted' | 'rejected' | 'expired' | null;
    appointmentGroupId?: string | null;
    appointmentGroupOrder?: number | null;
    appointmentGroupSize?: number | null;
    compositionId?: string | null;
    dependencyServiceId?: string | null;
    phaseConfig?: ServicePhaseConfig | null;
    phaseOperatorAssignments?: ServicePhaseOperatorAssignments | null;
    phaseOverlapOverrides?: ServicePhaseOverlapOverrides | null;
  },
>(
  left: T,
  right: T,
) => {
  const leftCreatedAt = Date.parse(left.createdAt ?? '') || 0;
  const rightCreatedAt = Date.parse(right.createdAt ?? '') || 0;
  if (leftCreatedAt !== rightCreatedAt) {
    return leftCreatedAt - rightCreatedAt;
  }

  const leftStatusRank = getAgendaRequestStatusRank(left);
  const rightStatusRank = getAgendaRequestStatusRank(right);
  if (leftStatusRank !== rightStatusRank) {
    return leftStatusRank - rightStatusRank;
  }

  const leftCompletenessRank = getAgendaRequestCompletenessRank(left);
  const rightCompletenessRank = getAgendaRequestCompletenessRank(right);
  if (leftCompletenessRank !== rightCompletenessRank) {
    return leftCompletenessRank - rightCompletenessRank;
  }

  return left.id.localeCompare(right.id);
};
const buildBlockedQuickBookingCustomerIdentityKeys = ({
  customers,
  appointments,
  appointmentDate,
  appointmentTime,
  selectedDurationMinutes,
  resolveAppointmentDurationMinutes,
}: {
  customers: { nome: string; email?: string | null }[];
  appointments: Pick<
    AppuntamentoItem,
    'data' | 'ora' | 'cliente' | 'servizio' | 'durataMinuti'
  >[];
  appointmentDate: string;
  appointmentTime: string;
  selectedDurationMinutes: number;
  resolveAppointmentDurationMinutes: (
    appointment: Pick<AppuntamentoItem, 'servizio' | 'durataMinuti'>,
  ) => number;
}) => {
  const blockedCustomerIdentityKeys = new Set<string>();
  const normalizedAppointmentTime = appointmentTime.trim().slice(0, 5);
  if (!normalizedAppointmentTime || selectedDurationMinutes <= 0) {
    return blockedCustomerIdentityKeys;
  }

  const customersByName = new Map<
    string,
    { nome: string; email?: string | null }[]
  >();

  customers.forEach((customer) => {
    const customerNameKey = normalizeAgendaCustomerIdentityText(customer.nome);
    if (!customerNameKey) return;

    const current = customersByName.get(customerNameKey) ?? [];
    current.push(customer);
    customersByName.set(customerNameKey, current);
  });

  const selectedStartMinutes = timeToMinutes(normalizedAppointmentTime);
  const selectedEndMinutes =
    selectedStartMinutes + Math.max(0, selectedDurationMinutes);

  appointments.forEach((appointment) => {
    const appointmentDateValue = (
      appointment.data ?? getTodayDateString()
    ).trim();
    const appointmentTimeValue = appointment.ora.trim().slice(0, 5);

    if (appointmentDateValue !== appointmentDate) {
      return;
    }

    const existingStartMinutes = timeToMinutes(appointmentTimeValue);
    const existingEndMinutes =
      existingStartMinutes +
      Math.max(0, resolveAppointmentDurationMinutes(appointment));

    if (!(
      selectedStartMinutes < existingEndMinutes &&
      selectedEndMinutes > existingStartMinutes
    )) {
      return;
    }

    const matchingCustomers =
      customersByName.get(
        normalizeAgendaCustomerIdentityText(appointment.cliente),
      ) ?? [];

    matchingCustomers.forEach((customer) => {
      blockedCustomerIdentityKeys.add(
        buildAgendaCustomerIdentityKey({
          fullName: customer.nome,
          email: customer.email,
        }),
      );
    });
  });

  return blockedCustomerIdentityKeys;
};
const DAY_CARD_WIDTH = IS_ANDROID ? 57 : 56;
