const getNativeWeekResizeIndicatorHeight = (contentHeight: number) => {
  'worklet';
  const safeContentHeight = Math.max(1, contentHeight);

  // A Panorama max una riga reale da 5 minuti misura 23 px. La linguetta
  // ordinaria da 18 px lascerebbe meno spazio della singola riga obbligatoria
  // cliente+servizio: soltanto in questo caso estremo la rendiamo compatta.
  if (safeContentHeight < 30) {
    return Math.max(9, Math.min(12, safeContentHeight - 11));
  }

  return Math.max(18, Math.min(27, safeContentHeight * 0.16));
};
const getWebWeekResizeIndicatorHeight = (contentHeight: number) => {
  'worklet';
  const safeContentHeight = Math.max(1, contentHeight);

  // Il mouse conserva la presa standard da 27 px. Solo la riga web minima da
  // 30 px la comprime quanto basta per lasciare una riga informativa reale.
  // Schede da 5 minuti: presa da 8 px, il resto alla riga di testo.
  if (safeContentHeight < 30) return 8;
  return safeContentHeight < 38
    ? Math.max(18, Math.min(27, safeContentHeight - 10))
    : 27;
};
