const hasConfiguredAgendaOperatorsForRole = (
  roleName: string,
  operators: { mestiere?: string | null }[],
) => {
  const normalizedRole = normalizeRoleName(roleName);
  if (!normalizedRole) return false;

  return operators.some(
    (item) => normalizeRoleName(item.mestiere ?? '') === normalizedRole,
  );
};

const shouldWarnAgendaAboutMissingOperatorsForRole = ({
  roleName,
  services,
  operators,
}: {
  roleName: string;
  services: { mestiereRichiesto?: string | null }[];
  operators: { mestiere?: string | null }[];
}) => {
  const normalizedRole = normalizeRoleName(roleName);
  if (!normalizedRole) return false;
  if (hasConfiguredAgendaOperatorsForRole(roleName, operators)) return false;

  const distinctRoles = new Set(
    [...services.map((item) => item.mestiereRichiesto ?? ''), roleName]
      .map((item) => normalizeRoleName(item))
      .filter(Boolean),
  );

  return distinctRoles.size > 1;
};

const formatAgendaRoleLabel = (value?: string | null) => {
  const trimmedValue = (value ?? '').trim();
  if (!trimmedValue) {
    return '';
  }

  return trimmedValue
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => {
      const lowerWord = word.toLocaleLowerCase('it-IT');
      return (
        lowerWord.charAt(0).toLocaleUpperCase('it-IT') + lowerWord.slice(1)
      );
    })
    .join(' ');
};

