const AGENDA_SERVICE_IDENTITY_COLORS = SERVICE_IDENTITY_COLORS;

const hashAgendaColorIdentity = (value: string) => {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
};

const getAgendaHexColorMetrics = (value: string) => {
  const normalized = value.trim().replace('#', '');
  if (!/^[0-9a-fA-F]{6}$/.test(normalized)) return null;

  const red = Number.parseInt(normalized.slice(0, 2), 16);
  const green = Number.parseInt(normalized.slice(2, 4), 16);
  const blue = Number.parseInt(normalized.slice(4, 6), 16);
  const normalizedRed = red / 255;
  const normalizedGreen = green / 255;
  const normalizedBlue = blue / 255;
  const maximum = Math.max(normalizedRed, normalizedGreen, normalizedBlue);
  const minimum = Math.min(normalizedRed, normalizedGreen, normalizedBlue);
  const delta = maximum - minimum;
  const lightness = (maximum + minimum) / 2;
  const saturation =
    delta === 0 ? 0 : delta / (1 - Math.abs(2 * lightness - 1));
  let hue = 0;

  if (delta > 0) {
    if (maximum === normalizedRed) {
      hue = 60 * (((normalizedGreen - normalizedBlue) / delta) % 6);
    } else if (maximum === normalizedGreen) {
      hue = 60 * ((normalizedBlue - normalizedRed) / delta + 2);
    } else {
      hue = 60 * ((normalizedRed - normalizedGreen) / delta + 4);
    }
  }

  if (hue < 0) hue += 360;
  return { red, green, blue, hue, saturation };
};

const areAgendaColorsVisuallySimilar = (
  firstColor: string,
  secondColor: string,
) => {
  const first = getAgendaHexColorMetrics(firstColor);
  const second = getAgendaHexColorMetrics(secondColor);
  if (!first || !second) return false;

  const rgbDistance = Math.sqrt(
    (first.red - second.red) ** 2 +
      (first.green - second.green) ** 2 +
      (first.blue - second.blue) ** 2,
  );
  const rawHueDistance = Math.abs(first.hue - second.hue);
  const hueDistance = Math.min(rawHueDistance, 360 - rawHueDistance);

  return (
    rgbDistance < 118 ||
    (first.saturation > 0.35 && second.saturation > 0.35 && hueDistance < 34)
  );
};

