type PromotedOccasionalCustomer = { id: string; full_name: string; phone: string };
const OccasionalCustomerPromotion = React.memo(function OccasionalCustomerPromotion({
  appointmentId, name, phone, onSaved,
}: {
  appointmentId: string; name: string; phone: string;
  onSaved: (customer: PromotedOccasionalCustomer) => void;
}) {
  const styles=React.useContext(AgendaPremiumStyleContext)??baseAgendaStyles;

  const [expanded, setExpanded] = useState(false);
  const [customerName, setCustomerName] = useState(name);
  const [customerPhone, setCustomerPhone] = useState(phone);
  const [saving, setSaving] = useState(false);
  const savingRef = useRef(false);
  const [errorText, setErrorText] = useState('');
  const save = async () => {
    if (savingRef.current) return;
    if (!customerName.trim() || !isValidPhone10(customerPhone)) {
      setErrorText('Per la rubrica inserisci nome e telefono valido (9 o 10 cifre).');
      return;
    }
    savingRef.current = true;
    setSaving(true);
    setErrorText('');
    try {
      const result = await supabase.rpc('save_occasional_customer_v1', {
        p_appointment_id: appointmentId, p_name: customerName.trim(), p_phone: customerPhone.trim(),
      });
      if (result.error) throw result.error;
      if (!result.data?.ok || !result.data.customer?.id) {
        setErrorText(result.data?.message || 'Cliente non salvato. Riprova.');
        return;
      }
      onSaved(result.data.customer);
    } catch {
      setErrorText('Salvataggio non confermato. Riprova: non verranno creati duplicati.');
    } finally {
      savingRef.current = false;
      setSaving(false);
    }
  };
  return <View style={styles.quickSectionBlock}>
    <Text style={styles.quickCustomerRequiredHint}>Cliente occasionale · {name}{phone ? ` · ${phone}` : ''}</Text>
    {expanded && <>
      <ClearableTextInput style={styles.input} value={customerName} onChangeText={setCustomerName} placeholder="Nome cliente" editable={!saving} />
      <ClearableTextInput style={styles.input} value={customerPhone} onChangeText={(value) => setCustomerPhone(limitPhoneToTenDigits(value))} placeholder="Telefono per la rubrica" keyboardType="phone-pad" editable={!saving} />
      {!!errorText && <Text style={styles.fieldErrorText}>{errorText}</Text>}
    </>}
    <HapticTouchable style={styles.darkButton} disabled={saving} onPress={() => expanded ? void save() : setExpanded(true)} hapticType="light">
      <Text style={styles.darkButtonText}>{saving ? 'Salvataggio…' : 'Salva in rubrica'}</Text>
    </HapticTouchable>
  </View>;
});

