const hasWeekDragOperatorPlacementConflict = (
  preview?: WeekSwapPreview | null,
) => !!(preview && (preview.hasOverlap || preview.displacedTargetHasOverlap));

const hasWeekDragSchedulingConflict = (preview?: WeekSwapPreview | null) =>
  !!(preview && hasWeekDragOperatorPlacementConflict(preview));

const getWeekDragLiveConflictLabel = (preview: WeekSwapPreview) => {
  if (preview.hasOverlap) {
    return preview.overlapMinutes
      ? `SOVRAPP. ${preview.overlapMinutes} MIN`
      : 'SOVRAPPOSIZIONE';
  }
  if (preview.displacedTargetHasOverlap) return 'SCAMBIO OCCUPATO';
  return '';
};

const buildWeekDragPreviewVisualKey = (preview: WeekSwapPreview) =>
  [
    preview.targetDate,
    preview.targetTime,
    preview.targetLaneKey ?? '',
    preview.phaseScope ?? '',
    preview.targetAppointment?.id ?? '',
    preview.targetAppointment?.renderedPhase ?? '',
    preview.displacedTargetAppointment?.id ?? '',
    preview.displacedTargetAppointment?.renderedPhase ?? '',
    preview.displacedTargetAppointment?.data ?? '',
    preview.displacedTargetAppointment?.ora ?? '',
    preview.displacedTargetVisualTime ?? '',
    preview.displacedTargetLaneKey ?? '',
    preview.displacedTargetHasOverlap ? 'displaced-overlap' : 'displaced-free',
    preview.hasOverlap ? 'overlap' : 'free',
    preview.tailOverlapOnly ? 'tail-overlap' : 'mixed-overlap',
    preview.overlapMinutes ?? 0,
    preview.overlapStartTime ?? '',
    preview.overlapAppointmentLabels?.join('~') ?? '',
    preview.poseCoverageWarning ?? '',
    preview.hasCustomerOverlap ? 'customer-overlap' : 'customer-free',
    preview.customerOverlapAppointmentLabels?.join('~') ?? '',
    preview.targetOperatorNotEnabledForService
      ? 'operator-warning'
      : 'operator-enabled',
    preview.targetOperatorServiceWarning ?? '',
    preview.moveAllPhasesBlockedReason ?? '',
    preview.resolvedSourceAppointment?.ora ?? '',
    preview.resolvedSourceAppointment?.durataMinuti ?? '',
    preview.invalidReason ?? '',
  ].join('|');

function WeekDragLiveConflictOverlay({
  preview,
}: {
  preview?: WeekSwapPreview | null;
}) {
  const styles=React.useContext(AgendaPremiumStyleContext)??baseAgendaStyles;

  if (!IS_WEB || !hasWeekDragSchedulingConflict(preview) || !preview) {
    return null;
  }

  return (
    <View pointerEvents="none" style={styles.weekDragLiveConflictOverlay}>
      <View style={styles.weekDragLiveConflictPill}>
        <Ionicons name="warning" size={10} color="#FFFFFF" />
        <Text
          numberOfLines={1}
          adjustsFontSizeToFit
          minimumFontScale={0.62}
          style={styles.weekDragLiveConflictText}
        >
          {getWeekDragLiveConflictLabel(preview)}
        </Text>
      </View>
    </View>
  );
}

