const normalizeWeekReorganizationPauseMinutes = (value: unknown) => {
  const minutes = Number(value);
  if (!Number.isFinite(minutes)) return 0;
  return Math.max(0, Math.min(180, Math.round(minutes / 5) * 5));
};

