type WeekCompositionPauseResizeImpact = {
  groupId: string;
  followingAppointmentId: string;
  previousPauseMinutes: number;
  nextPauseMinutes: number;
  consumedPauseMinutes: number;
};

const resolveWeekCompositionPauseResizeImpact = ({
  appointment,
  linkedAppointments,
  previousPauseMinutes,
  currentDurationMinutes,
  nextDurationMinutes,
  fallbackDate,
}: {
  appointment: AppuntamentoItem;
  linkedAppointments: AppuntamentoItem[];
  previousPauseMinutes: number;
  currentDurationMinutes: number;
  nextDurationMinutes: number;
  fallbackDate: string;
}): WeekCompositionPauseResizeImpact | null => {
  const groupId = appointment.appointmentGroupId?.trim() ?? '';
  const safePreviousPauseMinutes =
    normalizeWeekReorganizationPauseMinutes(previousPauseMinutes);
  if (
    !groupId ||
    safePreviousPauseMinutes <= 0 ||
    nextDurationMinutes <= currentDurationMinutes
  ) {
    return null;
  }

  const orderedAppointments = linkedAppointments
    .filter((item) => item.appointmentGroupId?.trim() === groupId)
    .sort(
      (first, second) =>
        (first.appointmentGroupOrder ?? Number.MAX_SAFE_INTEGER) -
          (second.appointmentGroupOrder ?? Number.MAX_SAFE_INTEGER) ||
        getAppointmentDateTime(
          first.data ?? fallbackDate,
          first.ora,
        ).getTime() -
          getAppointmentDateTime(
            second.data ?? fallbackDate,
            second.ora,
          ).getTime(),
    );
  const appointmentIndex = orderedAppointments.findIndex(
    (item) => item.id === appointment.id,
  );
  const followingAppointment = orderedAppointments[appointmentIndex + 1];
  if (appointmentIndex < 0 || !followingAppointment) return null;

  const nextAppointmentEnd =
    getAppointmentDateTime(
      appointment.data ?? fallbackDate,
      appointment.ora,
    ).getTime() +
    nextDurationMinutes * 60_000;
  const followingStart = getAppointmentDateTime(
    followingAppointment.data ?? fallbackDate,
    followingAppointment.ora,
  ).getTime();
  const availablePauseMinutes = Math.max(
    0,
    Math.floor((followingStart - nextAppointmentEnd) / 60_000),
  );
  const nextPauseMinutes = Math.min(
    safePreviousPauseMinutes,
    normalizeWeekReorganizationPauseMinutes(availablePauseMinutes),
  );
  if (nextPauseMinutes >= safePreviousPauseMinutes) return null;

  return {
    groupId,
    followingAppointmentId: followingAppointment.id,
    previousPauseMinutes: safePreviousPauseMinutes,
    nextPauseMinutes,
    consumedPauseMinutes: safePreviousPauseMinutes - nextPauseMinutes,
  };
};

