      const events = host.__salonAgendaInputs ?? (host.__salonAgendaInputs = []);
      events.push({at:Date.now(), changed:changed.map(key => ({key, equal:JSON.stringify(inputs[key])===JSON.stringify(perfInputsRef.current[key]), value: ['data','salonId','appLanguage'].includes(key) ? inputs[key] : undefined, fields: Array.isArray(inputs[key]) && Array.isArray(perfInputsRef.current[key]) ? (inputs[key] as Record<string, unknown>[]).flatMap((item,i)=> {const prev=(perfInputsRef.current[key] as Record<string, unknown>[])[i];return item && typeof item === 'object' && prev ? Object.keys(item).filter(field=>JSON.stringify(item[field])!==JSON.stringify(prev[field])).map(field=>({index:i,field,old:prev[field],new:item[field]})) : [];}).slice(0,4):undefined}))});
